#skapa lista med [1/window_size, 1/window_size] av längd window_size
#convolve summerar alltså alla data[0-window_size] * 1/window_size och sedan flyttas startpositionen ett steg
#flaggan "valid" gör så att om det inte finns plats att flytta ett steg längre stannar den. (hela fönstret måste vara fullt)
def float_mean(data, window_size):
	return np.convolve(data, np.ones(window_size) / window_size, "valid")

